pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        // Ensure recipient is not zero address and is a payable address
        vm.assume(recipient != address(0));
        // The recipient must be able to receive Ether
        vm.assume(recipient != address(c));

        // Set up the call: record the initial contract balance and call getFirstWithdrawalBonus
        uint256 balanceBefore = address(c).balance;

        // Try the call and catch any revert
        bool success;
        try c.getFirstWithdrawalBonus(recipient) {
            success = true;
        } catch {
            success = false;
        }

        uint256 balanceAfter = address(c).balance;

        // The invariant: if the call succeeds, the recipient must have consumed the bonus
        // and the contract balance must have changed appropriately (Ether sent out).
        // Specifically, if success, then claimedBonus[recipient] must be true AND balance change
        // must reflect a 100 wei decrease (since getFirstWithdrawalBonus transfers 100 wei as reward).
        // In the bug, the transfer can fail but the state is still updated (reward cleared, claimedBonus set),
        // breaking the link between success and balance change.
        assertTrue(
            !success || (c.claimedBonus(recipient) && balanceBefore - balanceAfter == 100)
        );
    }
}

