import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant owner = address(0x1000);
    function setUp() public {
        c = new C();
        vm.deal(owner, 10 ether);
    }
    function testFuzz_property(address recipient, uint256 seed) public {
        vm.assume(recipient != address(0) && recipient != address(c));
        // Use seed to generate a boolean to decide whether to use getFirstWithdrawalBonus or direct withdrawReward
        bool useBonus = (seed % 2) == 0;

        // Ensure contract has enough Ether to cover withdrawals
        vm.deal(address(c), 1000 ether);
        uint256 initialContractBalance = address(c).balance;

        // Set up rewardsForA for recipient through getFirstWithdrawalBonus if chosen
        if (useBonus) {
            vm.prank(owner);
            c.getFirstWithdrawalBonus{value: 100}(recipient);
        } else {
            // Directly set rewardsForA by calling getFirstWithdrawalBonus anyway since no public setter exists
            vm.prank(owner);
            c.getFirstWithdrawalBonus{value: 100}(recipient);
        }

        // Record the rewardsForA balance before any withdrawal
        uint256 recordedReward = c.rewardsForA(recipient);

        // Perform withdrawReward
        vm.prank(recipient);
        try c.withdrawReward(recipient) returns (bool ok) {
            // If successful, assert invariant
            uint256 finalReward = c.rewardsForA(recipient);
            uint256 finalContractBalance = address(c).balance;
            // Invariant: finalReward must be 0 (withdrawn) AND contract balance decreased accordingly
            // But the bug leaves finalReward unchanged, enabling double withdrawal.
            // We check: finalReward == 0 || (finalContractBalance < initialContractBalance - recordedReward) fails for bug.
            assertTrue(finalReward == 0);
        } catch {
            // If revert, invariant holds vacuously
        }
    }
}

